<?php require_once __DIR__.'/../config/auth.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{db()->beginTransaction();$book=db()->prepare('SELECT * FROM livros WHERE id=? FOR UPDATE');$book->execute([(int)$_POST['livro_id']]);$b=$book->fetch();if(!$b||$b['quantidade_disponivel']<1)throw new RuntimeException('Este livro não está disponível.');$date=$_POST['data_prevista_devolucao']?:date('Y-m-d',strtotime('+15 days'));$s=db()->prepare('INSERT INTO emprestimos(usuario_id,livro_id,data_emprestimo,data_prevista_devolucao,status,observacao) VALUES(?,?,?, ?,"ativo",?)');$s->execute([(int)$_POST['usuario_id'],(int)$_POST['livro_id'],$_POST['data_emprestimo'],$date,trim($_POST['observacao'])]);db()->prepare('UPDATE livros SET quantidade_disponivel=quantidade_disponivel-1 WHERE id=?')->execute([$b['id']]);db()->commit();flash('success','Empréstimo realizado com sucesso.');redirect('admin/emprestimos.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}}$students=db()->query("SELECT id,nome,ra FROM usuarios WHERE tipo='aluno' AND status='ativo' ORDER BY nome")->fetchAll();$books=db()->query('SELECT id,titulo,autor,quantidade_disponivel FROM livros WHERE quantidade_disponivel>0 ORDER BY titulo')->fetchAll();$pageTitle='Novo empréstimo';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><form class="panel" method="post" style="max-width:760px"><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><div class="form-group"><label>Aluno</label><select required name="usuario_id"><option value="">Selecione</option><?php foreach($students as $u):?><option value="<?=$u['id']?>"><?=e($u['nome'])?> — <?=e($u['ra'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Livro</label><select required name="livro_id"><option value="">Selecione</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=e($b['titulo'])?> — <?=e($b['autor'])?> (<?=$b['quantidade_disponivel']?>)</option><?php endforeach;?></select></div><div class="form-grid"><div class="form-group"><label>Data de retirada</label><input required type="date" name="data_emprestimo" value="<?=date('Y-m-d')?>"></div><div class="form-group"><label>Devolução prevista</label><input type="date" name="data_prevista_devolucao" value="<?=date('Y-m-d',strtotime('+15 days'))?>"></div></div><div class="form-group"><label>Observação</label><textarea name="observacao"></textarea></div><button class="btn">Registrar empréstimo</button></form><?php require __DIR__.'/../includes/dashboard-footer.php';?>
